from scipy.optimize import least_squares
one=np.ones_like(t)
def mk(G):
    return np.column_stack([G,P*G,P**2*G,P**3*G,P,P**2,P**3,P*t,P**2*t,t,one])
def runfit(gfun,p0):
    def r(p):
        X=mk(gfun(p)); return dP_dt-X@np.linalg.lstsq(X,dP_dt,rcond=None)[0]
    s=least_squares(r,p0)
    return np.mean(s.fun**2)/np.var(dP_dt), s.x
