from scipy.optimize import least_squares
one=np.ones_like(t)
def mk(p):
    G1=np.tanh(p[0]*t); G2=np.tanh(p[1]*t)
    return np.column_stack([G1,P*G2,P**2*G2,P**3*G2,P*G1,P**2*G1,P,P**2,P**3,P*t,P**2*t,t,one])
def r(p):
    X=mk(p); return dP_dt-X@np.linalg.lstsq(X,dP_dt,rcond=None)[0]
best=None
for a in [0.15,0.25,0.4]:
    for b in [0.1,0.25,0.5]:
        s=least_squares(r,[a,b],xtol=1e-15,ftol=1e-15,gtol=1e-15)
        e=np.mean(s.fun**2)/np.var(dP_dt)
        if best is None or e<best[0]: best=(e,s.x)
X=mk(best[1]); c=np.linalg.lstsq(X,dP_dt,rcond=None)[0]
